## Error Logging

```typescript
interface ErrorLog {
  timestamp: string
  level: 'error' | 'warn' | 'info'
  message: string
  code?: string
  stack?: string
  context?: Record<string, unknown>
  userId?: string
  requestId?: string
}

class Logger {
  private static instance: Logger

  static getInstance(): Logger {
    if (!Logger.instance) {
      Logger.instance = new Logger()
    }
    return Logger.instance
  }

  error(error: Error | AppError, context?: Record<string, unknown>) {
    const log: ErrorLog = {
      timestamp: new Date().toISOString(),
      level: 'error',
      message: error.message,
      stack: error.stack,
      context,
    }

    if (error instanceof AppError) {
      log.code = error.code
    }

    // In development, log to console
    if (process.env.NODE_ENV === 'development') {
      console.error(log)
    }

    // In production, send to logging service
    if (process.env.NODE_ENV === 'production') {
      this.sendToLoggingService(log)
    }
  }

  private async sendToLoggingService(log: ErrorLog) {
    // Send to Sentry, LogRocket, DataDog, etc.
    try {
      await fetch('/api/logs', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(log),
      })
    } catch {
      // Fail silently - don't throw errors in error handling
      console.error('Failed to send log:', log)
    }
  }
}

export const logger = Logger.getInstance()
